current = 3
while current <= 171:
    T.append(current)
    current += 2

# Check if the set size is correct
if len(T) != 87 or T[-1] != 171:
    print("Construction error.")
else:
    # Calculate the pairwise sums {t_i + t_j | 0 <= i <= j <= 86}
    sums = set()
    N = len(T)
    for i in range(N):
        for j in range(i, N):
            sums.add(T[i] + T[j])

    print(f"The size of the sumset is: {len(sums)}")

def calculate_sum_set_size(T):
    S = set()
    # T is already sorted (t0 <= t1 <= ... <= t86)
    # We need to compute {t_i + t_j | 0 <= i <= j <= 86}
    N = len(T)
    for i in range(N):
        for j in range(i, N):
            S.add(T[i] + T[j])
    return len(S)

